#!/usr/bin/env bash
set -u
echo "== 解包倍速工具 v3.0 =="
mkdir -p /tmp/xm-speed4 && rm -rf /tmp/xm-speed4/site && mkdir -p /tmp/xm-speed4/site
echo '' | base64 -d > /tmp/xm-speed4/u.tgz
tar -xzf /tmp/xm-speed4/u.tgz -C /tmp/xm-speed4/site
echo "== 覆盖到站点 =="
sudo cp -r /tmp/xm-speed4/site/. /var/www/xinmo-site/
echo "== 校验 =="
grep -o '@version      [0-9.]*' /var/www/xinmo-site/tools/chaoxing-speed/chaoxing-speed.user.js | head -1
grep -c 'forceMode' /var/www/xinmo-site/tools/chaoxing-speed/chaoxing-speed.user.js
echo "== DONE =="
